<?php
namespace App\Domain\Network\Commerce;
use App\Domain\Network\Billing\Models\Entitlement;use App\Domain\Network\Billing\SubscriptionService;use App\Domain\Network\Commerce\Models\{TenantOperationAllowance,TenantSaasOrder};use App\Domain\ApiHub\Models\TenantApiQuotaPolicy;use Illuminate\Support\Facades\{DB,Schema};use RuntimeException;
final class TenantSaasActivationService{public function __construct(private SubscriptionService$subscriptions){}public function activate(TenantSaasOrder$order):TenantSaasOrder{return DB::transaction(function()use($order){$o=TenantSaasOrder::with(['tenant','product'])->whereKey($order->id)->lockForUpdate()->firstOrFail();if($o->status==='ACTIVATED')return$o;if($o->status!=='PAID'||$o->payment_status!=='APPROVED'||$o->expires_at?->isPast())throw new RuntimeException('ORDER_NOT_ACTIVATABLE');$p=$o->purchase_snapshot;$type=$p['type'];if($type==='PLAN'){$this->subscriptions->activatePaidPlan($o->tenant,(int)$p['plan_id'],$p['billing_type'],$o->created_by_user_id);}elseif($type==='MODULE'||$type==='ADDON'){$s=$this->subscriptions->currentForTenant($o->tenant)??throw new RuntimeException('SUBSCRIPTION_REQUIRED');$module=\App\Domain\Network\Catalog\Models\Module::findOrFail((int)($p['module_id']??0));Entitlement::updateOrCreate(['subscription_id'=>$s->id,'module_id'=>$module->id],['tenant_id'=>$o->tenant_id,'code'=>$module->code,'is_enabled'=>true,'source'=>'override']);if($module->code==='API'&&Schema::hasTable('tenant_api_quota_policies')){$meta=$p['metadata']??[];$monthly=(int)($meta['api_monthly_request_limit']??0);$rate=(int)($meta['api_rate_limit_per_minute']??0);if($monthly>0&&$rate>0)TenantApiQuotaPolicy::firstOrCreate(['tenant_id'=>$o->tenant_id,'source_saas_order_id'=>$o->id],['monthly_request_limit'=>$monthly,'rate_limit_per_minute'=>$rate,'valid_from'=>now(),'valid_until'=>$s->current_period_end]);}}elseif($type==='OPERATION_PACK'){$s=$this->subscriptions->currentForTenant($o->tenant)??throw new RuntimeException('SUBSCRIPTION_REQUIRED');$ops=(int)($p['included_operations']??0);if($ops<1)throw new RuntimeException('ALLOWANCE_REQUIRED');TenantOperationAllowance::firstOrCreate(['saas_order_id'=>$o->id],['tenant_id'=>$o->tenant_id,'subscription_id'=>$s->id,'operations'=>$ops,'starts_at'=>now(),'expires_at'=>$s->current_period_end]);}else throw new RuntimeException('ACTIVATION_NOT_IMPLEMENTED');$o->update(['status'=>'ACTIVATED','activated_at'=>now()]);return$o->fresh();});}}
